#!/usr/bin/env bash\n\n# If no argument is supplied, read from stdin\nif [ $# -eq 0 ]; then\n  INPUT="/dev/stdin"\nelse\n  INPUT="$1"\nfi\n\n# Verify the input exists (skip check for stdin)\nif [ "$INPUT" != "/dev/stdin" ] && [ ! -e "$INPUT" ]; then\n  echo "⚠️  No such file: $INPUT"\n  exit 1\nfi\n\n# Use wc to get lines, words, and bytes\nread LINES WORDS BYTES <<<$(wc -l -w -c "$INPUT" | awk '{print $1, $2, $3}')\n\n# Print the whimsical report\necho "🧭 Apocalypse Wordcount Report 🧭"\necho "Lines: $LINES"\necho "Words: $WORDS"\necho "Bytes: $BYTES"\n\nexit 0
